import type { Meta, StoryObj } from "@storybook/vue3";
import { Check } from "@kozmos-ds/icons/vue";
import { h } from "vue";
import { KozmosBadge } from "../../index";

/**
 * Vue's Badge: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port Badge`; Icon written by hand.
 */
type Args = Record<string, unknown>;
const SLOTS = ["counter", "icon", "children"];

const meta: Meta<Args> = {
  title: "Vue/Core/Data display/Badge",
  component: KozmosBadge,
  parameters: { layout: "centered" },
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key)) props[key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosBadge, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {
  args: {
    children: "Badge",
    variant: "default",
  },
};

export const Outline: Story = {
  args: {
    children: "Outline",
    variant: "outline",
  },
};

export const WithCounter: Story = {
  args: {
    children: "New",
    counter: 2,
    showCounter: true,
    variant: "secondary",
  },
};

export const DefaultWithCounter: Story = {
  args: {
    children: "Messages",
    counter: 3,
    showCounter: true,
    variant: "default",
  },
};

/** An icon Badge is an image, named by its `aria-label`; the icon is a slot. */
export const Icon: Story = {
  args: { "aria-label": "Verified", size: "icon", variant: "default" },
  render: (args) => ({
    setup: () => () => h(KozmosBadge, args, { icon: () => h(Check) }),
  }),
};
